solution.solution.c:
#include <stddef.h>

void set_to(int *target, int value)
{
    *target = value;
}

void add_to(int *total, int amount)
{
    *total += amount;
}

int *larger(int *a, int *b)
{
    return (*b > *a) ? b : a;
}

int value_or(const int *p, int fallback)
{
    if (p == NULL) return fallback;
    return *p;
}

unitTests:
TEST("setting through a pointer") { int x = 0; set_to(&x, 42); CHECK_EQ(x, 42); set_to(&x, -1); CHECK_EQ(x, -1); }
TEST("adding through a pointer") { int total = 10; add_to(&total, 5); add_to(&total, 7); CHECK_EQ(total, 22); }
TEST("the larger one, as a pointer") { int a = 3, b = 9; CHECK(larger(&a, &b) == &b); CHECK(larger(&b, &a) == &b); int c = 4, d = 4; CHECK(larger(&c, &d) == &c); *larger(&a, &b) = 0; CHECK_EQ(b, 0); }
TEST("a value or a fallback") { int x = 5; CHECK_EQ(value_or(&x, -1), 5); CHECK_EQ(value_or(NULL, -1), -1); }

